use std::{fs, hint::black_box, time::Instant};
fn main() {
 let mut files: Vec<_> = fs::read_dir("fixtures").unwrap().map(|e| e.unwrap().path()).filter(|p| p.extension().is_some_and(|s| s == "patch")).collect(); files.sort();
 let inputs: Vec<String> = files.iter().map(|p| fs::read_to_string(p).unwrap()).collect();
 for round in 0..10 { let fast = round % 2 == 1; let now = Instant::now(); let mut count = 0usize;
  for _ in 0..200 { for s in &inputs { for line in s.lines() { count += black_box(if fast { line.bytes().any(|b| (b < 32 && b != b'\t') || b == 127 || b == 0xc2) } else { line.chars().any(|c| c.is_control() && c != '\t') }) as usize; } } }
  println!("{} {} {}", if fast {"bytes"} else {"chars"}, now.elapsed().as_nanos(), count);
 }
}

