def median: sort | .[(length / 2 | floor)];
def summarize:
  map(.benchmarks[]) | group_by(.name) | map({
    name: .[0].name,
    median_ns: (map(.median_ns) | median),
    min_ns: (map(.median_ns) | min),
    max_ns: (map(.median_ns) | max),
    run_medians_ns: map(.median_ns),
    alloc_counts: (map(.alloc_count) | unique),
    alloc_bytes: (map(.alloc_bytes) | unique)
  });
if length != 10 or any(.[]; .sample_count != 15 or .sample_size != 20) then error("wrong measurement configuration") else . end |
(.[0:5] | summarize) as $base |
(.[5:10] | summarize) as $candidate |
[range(0; ($base | length)) | . as $i |
  $base[$i] as $b | $candidate[$i] as $c |
  if $b.name != $c.name then error("row mismatch") else . end |
  ($c.median_ns - $b.median_ns) as $delta |
  ([$b.max_ns-$b.min_ns, $c.max_ns-$c.min_ns] | max) as $spread |
  {package: $package, name: $b.name, baseline: $b, candidate: $c, delta_ns: $delta,
   delta_percent: (100 * $delta / $b.median_ns), spread_ns: $spread,
   regression: ($delta > 0.02 * $b.median_ns and $delta > $spread)}
]
